def existing_boxes(apps, schema_editor):
    """Boîtes existantes : année = année de création ; étagère / rack au format E03 / R01 ;
    type, année et n° déduits d'un nom déjà au format SCH-2026-01."""
    import re

    from apps.biobank.models import ABBR_TYPE, level_code

    StorageBox = apps.get_model("biobank", "StorageBox")
    for box in StorageBox.objects.all():
        box.year = box.created_at.year if box.created_at else None
        box.shelf, box.rack = level_code("E", box.shelf), level_code("R", box.rack)
        m = re.fullmatch(r"([A-Z]{2,4})-(\d{4})-(\d{2,})", box.name.upper())
        if m and m.group(1) in ABBR_TYPE:
            box.item_type, box.year, box.number = ABBR_TYPE[m.group(1)], int(m.group(2)), int(m.group(3))
        box.save(update_fields=["year", "shelf", "rack", "item_type", "number"])


